  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 24px;
  background:
    radial-gradient(circle at 15% 15%, rgba(255, 205, 112, 0.18), transparent 26rem),
    radial-gradient(circle at 85% 80%, rgba(126, 116, 255, 0.3), transparent 30rem),
    linear-gradient(160deg, #1e1944 0%, #12102a 55%, #090818 100%);
