.castle-card::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image: radial-gradient(rgba(255, 255, 255, 0.5) 1px, transparent 1px);
  background-size: 46px 46px;
  opacity: 0.22;
}

.eyebrow {
  margin: 0 0 10px;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: #ffd27a;
}

h1 {
  margin: 0;
  font-size: clamp(1.85rem, 6vw, 2.8rem);
  line-height: 1.05;
  letter-spacing: -0.03em;
}

.castle {
  position: relative;
  z-index: 1;
  display: block;
  width: min(78%, 320px);
  margin: 18px auto 8px;
  filter: drop-shadow(0 16px 22px rgba(0, 0, 0, 0.4));
}

.score-label {
  margin: 0;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: #b8afff;
}

.score {
  margin: 4px 0 18px;
  font-size: clamp(3.5rem, 16vw, 5.5rem);
  font-weight: 800;
  line-height: 1;
  color: #ffd27a;
  text-shadow: 0 0 32px rgba(255, 210, 122, 0.4);
  font-variant-numeric: tabular-nums;
