.add-point {
  position: relative;
  z-index: 1;
  width: min(100%, 300px);
  padding: 16px 28px;
  border: 0;
  border-radius: 999px;
  font: inherit;
  font-size: 1.08rem;
  font-weight: 800;
  letter-spacing: 0.02em;
  color: #241a03;
  cursor: pointer;
  background: linear-gradient(180deg, #ffe3a1, #ffbf4d);
  box-shadow:
    0 10px 0 #b97718,
    0 18px 30px rgba(0, 0, 0, 0.35);
  transition: transform 120ms ease, box-shadow 120ms ease;
