.add-point:hover {
  transform: translateY(-2px);
  box-shadow:
    0 12px 0 #b97718,
    0 22px 34px rgba(0, 0, 0, 0.38);
}

.add-point:active {
  transform: translateY(6px);
  box-shadow:
    0 4px 0 #b97718,
    0 8px 16px rgba(0, 0, 0, 0.3);
}

.add-point:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 4px;
}

.add-point.pop {
  animation: pop 220ms ease-out;
}

.hint {
  position: relative;
  z-index: 1;
  margin: 22px 0 0;
  font-size: 0.9rem;
  color: #bdb7e8;
}

@keyframes pop {
  50% {
    transform: translateY(4px) scale(0.97);
  }
}

@media (prefers-reduced-motion: reduce) {
  .add-point {
    transition: none;
  }

  .add-point.pop {
    animation: none;
  }
}

